 "genere": "prevedi",
 "titolo": "Ripasso: Terreni, Sfondi e Livelli",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends Node2D


func run():
	var camera_movement := Vector2(200, 0)
	var layer_scale := Vector2(0.5, 1.0)
	var apparent_movement = camera_movement * layer_scale
	return apparent_movement
",
   "domanda": "Quanto vale `apparent_movement` alla fine?",
   "spiegazione": "La proprietà `motion_scale` di un ParallaxLayer riduce lo scorrimento rispetto alla camera. Moltiplicando `Vector2(200, 0)` per `Vector2(0.5, 1.0)` si ottiene `Vector2(100, 0)`."
  },
  {
   "codice": "extends Node2D


func run():
	var chunk_size: float = 320.0
	var mirroring := Vector2(chunk_size * 2, 0.0)
	return mirroring.x
",
   "domanda": "Quanto vale la x di `mirroring`?",
   "spiegazione": "La proprietà `motion_mirroring` serve a ripetere lo sfondo. Moltiplicando `320.0 * 2` si ottiene `640.0`, la larghezza totale dell'area ripetuta."
  },
  {
   "codice": "extends Node2D


func run():
	var current_level: int = 1
	var total_levels: int = 3
	current_level += 1
	var is_last_level: bool = (current_level >= total_levels)
	return is_last_level
",
   "domanda": "Cosa restituisce `is_last_level`?",
   "spiegazione": "`current_level` parte da 1 e diventa 2 con `+= 1`. Poiché 2 non è maggiore o uguale a 3 (`total_levels`), la condizione è falsa (`false`)."
  },
