   "codice": "extends Node2D


func run():
	var coins_collected: int = 5
	var coins_required: int = 5
	var exit_unlocked: bool = coins_collected >= coins_required
	return exit_unlocked
",
   "domanda": "Cosa restituisce `exit_unlocked`?",
   "spiegazione": "Con 5 monete raccolte su 5 richieste, il confronto `5 >= 5` risulta vero (`true`), sbloccando l'accesso alla zona di traguardo."
  },
